# Let me map all character transformations needed across all examples
# And then build a minimal sequence

inputs = ['jxdi', 'wuhfje', 'ffcj', 'bxyuz', 'jdgzgc']
outputs = ['jfwdi', 'wuwwauje', 'auaucj', 'bfwyuz', 'jdxzxc']

# Create a comprehensive mapping of what needs to change
transformations = {}

for i in range(len(inputs)):
    input_str = inputs[i]
    output_str = outputs[i]
    print(f"{input_str} -> {output_str}")

    # Compare character by character
    max_len = max(len(input_str), len(output_str))
    for pos in range(max_len):
        input_char = input_str[pos] if pos < len(input_str) else None
        output_char = output_str[pos] if pos < len(output_str) else None

        if input_char and output_char and input_char != output_char:
            if input_char not in transformations:
                transformations[input_char] = []
            if output_char not in transformations[input_char]:
                transformations[input_char].append(output_char)
        elif input_char and not output_char:
            # Character removed
            print(f"  Character '{input_char}' removed at position {pos}")
        elif not input_char and output_char:
            # Character added
            print(f"  Character '{output_char}' added at position {pos}")

print("\nCharacter transformation map:")
for k, v in transformations.items():
    print(f"  '{k}' -> {v}")

